DG.put("ath-pakhyaan-charitr-likhyate/52",{"n":52,"title":null,"title_roman":null,"page":1209,"blocks":[{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1209},{"type":"verse","number":[1],"number_text":"੧।","page":1209,"lines":[{"gurmukhi":"ਉਤਰ ਦੇਸ ਨ੍ਰਿਪਤਿ ਇਕ ਭਾਰੋ। ਸੂਰਜ ਬੰਸ ਬਿਖੈ ਉਜਿਯਾਰੋ।","roman":"Utar des nripti ik bhaaro | sooraj bans bikhai ujiyaaro |","meaning_en":"","page":1209},{"gurmukhi":"ਇੰਦ੍ਰ ਪ੍ਰਭਾ ਤਾ ਕੀ ਪਟਰਾਨੀ। ਬਿਜੈ ਸਿੰਘ ਰਾਜਾ ਬਰ ਆਨੀ। ੧।","roman":"Indr prabhaa taa kee patraanee | bijai singh raajaa bar aanee | 1 |","meaning_en":"","page":1209}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1209},{"type":"verse","number":[2],"number_text":"੨।","page":1209,"lines":[{"gurmukhi":"ਏਕ ਸੁਤਾ ਤਾ ਕੇ ਭਵਨ ਅਮਿਤ ਰੂਪ ਕੀ ਖਾਨਿ।","roman":"Ek sutaa taa ke bhavan amit roop kee khaani |","meaning_en":"","page":1209},{"gurmukhi":"ਕਾਮ ਦੇਵ ਠਟਕੇ ਰਹਤ ਰਤਿ ਸਮ ਤਾਹਿ ਪਛਾਨਿ। ੨।","roman":"Kaam dev thatke rahat rati sam taahi pachhaani | 2 |","meaning_en":"","page":1209}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1209},{"type":"verse","number":[3],"number_text":"੩।","page":1209,"lines":[{"gurmukhi":"ਜੋਬਨ ਅਧਿਕ ਤਾਹਿ ਜਬ ਭਯੋ। ਲੈ ਤਾ ਕੋ ਗੰਗਾ ਪਿਤੁ ਗਯੋ।","roman":"Joban adhik taahi jab bhayo | lai taa ko gangaa pitu gayo |","meaning_en":"","page":1209},{"gurmukhi":"ਬਡੇ ਬਡੇ ਰਾਜਾ ਤਹ ਐਹੈ। ਤਿਨ ਮੈ ਭਲੋ ਹੇਰਿ ਤਹ ਦੈਹੈ। ੩।","roman":"Bade bade raajaa tah aihai | tin mai bhalo heri tah daihai | 3 |","meaning_en":"","page":1209}]},{"type":"verse","number":[4],"number_text":"੪।","page":1209,"lines":[{"gurmukhi":"ਚਲੇ ਚਲੇ ਗੰਗਾ ਪਹਿ ਆਏ। ਬੰਧੁ ਸੁਤਾ ਇਸਤ੍ਰਿਨ ਸੰਗ ਲ੍ਯਾਏ।","roman":"Chale chale gangaa pahi aae | bandhu sutaa istrin sang lyaae |","meaning_en":"","page":1209},{"gurmukhi":"ਸ੍ਰੀ ਜਾਨ੍ਹਵਿ ਕੋ ਦਰਸਨ ਕੀਨੋ। ਪੂਰਬ ਪਾਪ ਬਿਦਾ ਕਰਿ ਦੀਨੋ। ੪।","roman":"Sree jaanhavi ko darsan keeno | poorab paap bidaa kari deeno | 4 |","meaning_en":"","page":1209}]},{"type":"verse","number":[5],"number_text":"੫।","page":1211,"lines":[{"gurmukhi":"ਬਡੇ ਬਡੇ ਭੂਪਤਿ ਤਹ ਆਏ। ਤਵਨਿ ਕੁਅਰਿ ਕੋ ਸਕਲ ਦਿਖਾਏ।","roman":"Bade bade bhoopti tah aae | tavni kuari ko sakal dikhaae |","meaning_en":"","page":1211},{"gurmukhi":"ਇਨ ਪਰ ਦ੍ਰਿਸਟਿ ਸਭਨ ਪਰ ਕਰਿਯੈ। ਜੋ ਜਿਯ ਰੁਚੈ ਤਿਸੀ ਕੌ ਬਰਿਯੈ। ੫।","roman":"In par dristi sabhan par kariyai | jo jiy ruchai tisee kau bariyai | 5 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1211},{"type":"verse","number":[6],"number_text":"੬।","page":1211,"lines":[{"gurmukhi":"ਹੇਰਿ ਨ੍ਰਿਪਤਿ ਸੁਤ ਨ੍ਰਿਪਨ ਕੇ ਕੰਨ੍ਯਾ ਕਹੀ ਬਿਚਾਰ।","roman":"Heri nripti sut nripan ke kannyaa kahee bichaar |","meaning_en":"","page":1211},{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਸੁੰਦਰ ਸੁਘਰ ਬਰਹੋ ਵਹੈ ਕੁਮਾਰ। ੬।","roman":"Subhat singh sundar sughar barho vahai kumaar | 6 |","meaning_en":"","page":1211}]},{"type":"verse","number":[7],"number_text":"੭।","page":1211,"lines":[{"gurmukhi":"ਅਧਿਕ ਰੂਪ ਤਾ ਕੋ ਨਿਰਖਿ ਸਭ ਰਾਜਾ ਰਿਸਿ ਖਾਹਿ।","roman":"Adhik roop taa ko nirkhi sabh raajaa risi khaahi |","meaning_en":"","page":1211},{"gurmukhi":"ਜਿਯੋ ਕਿਯੋ ਯਾਹਿ ਬਿਵਾਹਿ ਕੈ ਗ੍ਰਿਹਿ ਅਪੁਨੇ ਲੈ ਜਾਹਿ। ੭।","roman":"Jiyo kiyo yaahi bivaahi kai grihi apune lai jaahi | 7 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1211},{"type":"verse","number":[8],"number_text":"੮।","page":1211,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਸਕਲ ਅਧਿਕ ਰਿਸਿ ਕਰੈ। ਹਾਥ ਹਥਯਾਰਨ ਊਪਰ ਧਰੈ।","roman":"Bhoopti sakal adhik risi karai | haath hathyaaran oopar dharai |","meaning_en":"","page":1211},{"gurmukhi":"ਕੁਪਿ ਕੁਪਿ ਬਚਨ ਬਕਤ੍ਰ ਤੇ ਕਹੈ। ਬਿਨੁ ਰਨ ਕਿਯੇ ਆਜੁ ਨਹਿ ਰਹੈ। ੮।","roman":"Kupi kupi bachan bakatr te kahai | binu ran kiye aaju nahi rahai | 8 |","meaning_en":"","page":1211}]},{"type":"verse","number":[9],"number_text":"੯।","page":1211,"lines":[{"gurmukhi":"ਰਾਇ ਪ੍ਰੋਹਿਤਨ ਲਿਯਾ ਬੁਲਾਈ। ਸੁਭਟ ਸਿੰਘ ਪ੍ਰਤਿ ਦਏ ਪਠਾਈ।","roman":"Raai prohitan liyaa bulaaee | subhat singh prati dae pathaaee |","meaning_en":"","page":1211},{"gurmukhi":"ਮੋ ਪਰ ਕਹੀ ਅਨੁਗ੍ਰਹੁ ਕਰਿਯੈ। ਬੇਦ ਬਿਧਾਨ ਸਹਿਤ ਇਹ ਬਰਿਯੈ। ੯।","roman":"Mo par kahee anugrahu kariyai | bed bidhaan sahit ih bariyai | 9 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1211},{"type":"verse","number":[10],"number_text":"੧੦।","page":1211,"lines":[{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਐਸੇ ਕਹੀ ਤ੍ਰਿਯ ਮੁਰ ਆਗੇ ਏਕ।","roman":"Subhat singh aise kahee triy mur aage ek |","meaning_en":"","page":1211},{"gurmukhi":"ਬ੍ਯਾਹ ਦੂਸਰੌ ਨ ਕਰੋ ਜੌ ਜਨ ਕਹੈ ਅਨੇਕ। ੧੦।","roman":"Byaah doosrau na karo jau jan kahai anek | 10 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1211},{"type":"verse","number":[11],"number_text":"੧੧।","page":1211,"lines":[{"gurmukhi":"ਪ੍ਰੋਹਿਤ ਭੂਪਤਿ ਸੌ ਇਹ ਉਚਰੈ। ਸੁਭਟ ਸਿੰਘ ਯਾ ਕੋ ਨਹਿ ਬਰੈ।","roman":"Prohit bhoopti sau ih uchrai | subhat singh yaa ko nahi barai |","meaning_en":"","page":1211},{"gurmukhi":"ਤਾ ਤੇ ਕਛੂ ਜਤਨ ਪ੍ਰਭ ਕੀਜੈ। ਇਹ ਕੰਨ੍ਯਾ ਅਵਰੈ ਨ੍ਰਿਪ ਦੀਜੈ। ੧੧।","roman":"Taa te kachhoo jatan prabh keejai | ih kannyaa avrai nrip deejai | 11 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1211},{"type":"verse","number":[12],"number_text":"੧੨।","page":1211,"lines":[{"gurmukhi":"ਤਬ ਕੰਨ੍ਯਾ ਐਸੇ ਕਹੀ ਬਚਨ ਪਿਤਾ ਕੇ ਸਾਥ।","roman":"Tab kannyaa aise kahee bachan pitaa ke saath |","meaning_en":"","page":1211},{"gurmukhi":"ਜੋ ਕੋ ਜੁਧ ਜੀਤੈ ਮੁਝੈ ਵਹੈ ਹਮਾਰੋ ਨਾਥ। ੧੨।","roman":"Jo ko judh jeetai mujhai vahai hamaaro naath | 12 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1211},{"type":"verse","number":[13],"number_text":"੧੩।","page":1211,"lines":[{"gurmukhi":"ਸਭ ਭੂਪਨ ਨ੍ਰਿਪ ਐਸ ਸੁਨਾਯੋ। ਆਪ ਜੁਧ ਕੋ ਬਿਵਤ ਬਨਾਯੋ।","roman":"Sabh bhoopan nrip ais sunaayo | aap judh ko bivat banaayo |","meaning_en":"","page":1211},{"gurmukhi":"ਜੋ ਕੋਊ ਤੁਮਲ ਜੁਧ ਹ੍ਯਾ ਕਰ ਹੈ। ਵਹੈ ਯਾਹਿ ਕੰਨ੍ਯਾ ਕਹੁ ਬਰਿ ਹੈ। ੧੩।","roman":"Jo ko'oo tumal judh hyaa kar hai | vahai yaahi kannyaa kahu bari hai | 13 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1211},{"type":"verse","number":[14],"number_text":"੧੪।","page":1211,"lines":[{"gurmukhi":"ਸੁਨਤ ਬਚਨ ਬੀਰਾਨ ਕੇ ਚਿਤ ਮੈ ਭਯਾ ਅਨੰਦ।","roman":"Sunat bachan beeraan ke chit mai bhayaa anand |","meaning_en":"","page":1211},{"gurmukhi":"ਮਥਿ ਸਮੁੰਦ੍ਰ ਦਲ ਪਾਇ ਹੈ ਆਜੁ ਕੁਅਰਿ ਮੁਖ ਚੰਦ। ੧੪।","roman":"Mathi samundr dal paai hai aaju kuari mukh chand | 14 |","meaning_en":"","page":1211}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1213},{"type":"verse","number":[15],"number_text":"੧੫।","page":1213,"lines":[{"gurmukhi":"ਸਭਨ ਜੁਧ ਕੇ ਸਾਜ ਬਨਾਏ। ਗੰਗਾ ਤੀਰ ਬੀਰ ਚਲਿ ਆਏ।","roman":"Sabhan judh ke saaj banaae | gangaa teer beer chali aae |","meaning_en":"","page":1213},{"gurmukhi":"ਪਹਿਰਿ ਕਵਚ ਸਭ ਸੂਰ ਸੁਹਾਵੈ। ਡਾਰਿ ਪਾਖਰੈ ਤੁਰੈ ਨਚਾਵੈ। ੧੫।","roman":"Pahiri kavach sabh soor suhaavai | daari paakhrai turai nachaavai | 15 |","meaning_en":"","page":1213}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":1213,"lines":[{"gurmukhi":"ਗਰਜੈ ਕਰੀ ਅਸ੍ਵ ਹਿਹਨਾਨੇ। ਪਹਿਰੇ ਕਵਚ ਸੂਰ ਨਿਜੁਕਾਨੇ।","roman":"Garjai karee asv hihnaane | pahire kavach soor nijukaane |","meaning_en":"","page":1213},{"gurmukhi":"ਕਿਨਹੂੰ ਕਾਢਿ ਖੜਗ ਕਰ ਲੀਨੋ। ਕਿਨਹੂੰ ਕੇਸਰਿਯਾ ਬਾਨਾ ਕੀਨੋ। ੧੬।","roman":"Kinhoon kaadhi kharag kar leeno | kinhoon kesriyaa baanaa keeno | 16 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1213},{"type":"verse","number":[17],"number_text":"੧੭।","page":1213,"lines":[{"gurmukhi":"ਕਿਨੂੰ ਤਿਲੌਨੇ ਬਸਤ੍ਰ ਕਰਿ ਕਟਿ ਸੋ ਕਸੀ ਕ੍ਰਿਪਾਨ।","roman":"Kinoon tilaune basatr kari kati so kasee kripaan |","meaning_en":"","page":1213},{"gurmukhi":"ਜੋ ਗੰਗਾ ਤਟ ਜੂਝਿ ਹੈ ਕਰਿ ਹੈ ਸ੍ਵਰਗ ਪਯਾਨ। ੧੭।","roman":"Jo gangaa tat joojhi hai kari hai svarag payaan | 17 |","meaning_en":"","page":1213}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":1213,"lines":[{"gurmukhi":"ਜੋਰਿ ਅਨਿਨ ਰਾਜਾ ਚੜੇ ਪਰਾ ਨਿਸਾਨੇ ਘਾਵ।","roman":"Jori anin raajaa chare paraa nisaane ghaav |","meaning_en":"","page":1213},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਜੋਧਾ ਲਰੇ ਅਧਿਕ ਹ੍ਰਿਦੈ ਕਰ ਚਾਵ। ੧੮।","roman":"Bhaati bhaati jodhaa lare adhik hridai kar chaav | 18 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1213},{"type":"verse","number":[19],"number_text":"੧੯।","page":1213,"lines":[{"gurmukhi":"ਤਬ ਕੰਨ੍ਯਾ ਸਭ ਸਖੀ ਬੁਲਾਈ। ਭਾਤਿ ਭਾਤਿ ਸੋ ਕਰੀ ਬਡਾਈ।","roman":"Tab kannyaa sabh sakhee bulaaee | bhaati bhaati so karee badaaee |","meaning_en":"","page":1213},{"gurmukhi":"ਕੈ ਲਰਿ ਕਰਿ ਸੁਰਸਰਿ ਤਟ ਮਰਿ ਹੌ। ਨਾਤਰ ਸੁਭਟ ਸਿੰਘ ਕਹ ਬਰਿ ਹੌ। ੧੯।","roman":"Kai lari kari surasri tat mari hau | naatar subhat singh kah bari hau | 19 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1213},{"type":"verse","number":[20],"number_text":"੨੦।","page":1213,"lines":[{"gurmukhi":"ਤਬ ਕੰਨ੍ਯਾ ਐਸੇ ਕਹੇ ਸਕਲ ਸਖਿਨ ਸੋ ਬੈਨ।","roman":"Tab kannyaa aise kahe sakal sakhin so bain |","meaning_en":"","page":1213},{"gurmukhi":"ਬਿਕਟ ਕਟਕ ਕੇ ਸੁਭਟ ਭਟ ਪਠਵੋ ਜਮ ਕੇ ਐਨ। ੨੦।","roman":"Bikat katak ke subhat bhat pathvo jam ke ain | 20 |","meaning_en":"","page":1213}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":1213,"lines":[{"gurmukhi":"ਸਕਲ ਸਖਿਨ ਕੋ ਸਸਤ੍ਰ ਦੈ ਅਵਰ ਕਵਚ ਪਹਿਰਾਇ।","roman":"Sakal sakhin ko sasatr dai avar kavach pahiraai |","meaning_en":"","page":1213},{"gurmukhi":"ਨਿਕਸਿ ਆਪੁ ਠਾਢੀ ਭਈ ਜੈ ਦੁੰਦਭੀ ਬਜਾਇ। ੨੧।","roman":"Niksi aapu thaadhee bhaee jai dundbhee bajaai | 21 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1213},{"type":"verse","number":[22],"number_text":"੨੨।","page":1213,"lines":[{"gurmukhi":"ਕੰਨ੍ਯਾ ਰਥ ਆਰੂੜਿਤ ਭਈ। ਜੋਧਿ ਸਮਗ੍ਰੀ ਸਭਿਯਨ ਦਈ।","roman":"Kannyaa rath aaroorit bhaee | jodhi samgree sabhiyan daee |","meaning_en":"","page":1213},{"gurmukhi":"ਸਫਾਜੰਗ ਮਹਿ ਤੁਰੈ ਨਚਾਏ। ਸੁਰ ਸੁਰਪਤਿ ਦੇਖਨ ਰਨ ਆਏ। ੨੨।","roman":"Saphaajang mahi turai nachaae | sur surapti dekhan ran aae | 22 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1213},{"type":"verse","number":[23],"number_text":"੨੩।","page":1213,"lines":[{"gurmukhi":"ਉਮਡੇ ਅਮਿਤ ਅਨੇਕ ਦਲ ਬਾਰਦ ਬੂੰਦ ਸਮਾਨ।","roman":"Umde amit anek dal baarad boond samaan |","meaning_en":"","page":1213},{"gurmukhi":"ਬਨਿ ਬਨਿ ਨ੍ਰਿਪ ਆਵਤ ਭਏ ਸਮਰ ਸੁਯੰਬਰ ਜਾਨ। ੨੩।","roman":"Bani bani nrip aavat bhae samar suyanbar jaan | 23 |","meaning_en":"","page":1213}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1213},{"type":"verse","number":[24],"number_text":"੨੪।","page":1213,"lines":[{"gurmukhi":"ਮਚਿਯੌ ਤੁਮਲ ਜੁਧ ਤਹ ਭਾਰੀ। ਨਾਚੇ ਸੂਰਬੀਰ ਹੰਕਾਰੀ।","roman":"Machiyau tumal judh tah bhaaree | naache soorbeer hankaaree |","meaning_en":"","page":1213},{"gurmukhi":"ਤਾਨਿ ਧਨੁਹਿਯਨ ਬਿਸਿਖ ਚਲਾਵਤ। ਮਾਇ ਮਰੇ ਪਦ ਕੂਕਿ ਸੁਨਾਵਤ। ੨੪।","roman":"Taani dhanuhiyan bisikh chalaavat | maai mare pad kooki sunaavat | 24 |","meaning_en":"","page":1213}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":1215,"lines":[{"gurmukhi":"ਜਿਹ ਬਚਿਤ੍ਰ ਦੇ ਬਾਨ ਲਗਾਵੈ। ਵਹੈ ਸੁਭਟ ਮ੍ਰਿਤੁ ਲੋਕ ਸਿਧਾਵੈ।","roman":"Jih bachitr de baan lagaavai | vahai subhat mritu lok sidhaavai |","meaning_en":"","page":1215},{"gurmukhi":"ਜਾ ਪਰ ਤਮਕਿ ਤੇਗ ਕੀ ਝਾਰੈ। ਤਾ ਕੋ ਮੂੰਡ ਕਾਟਿ ਹੀ ਡਾਰੈ। ੨੫।","roman":"Jaa par tamki teg kee jhaarai | taa ko moond kaati hee daarai | 25 |","meaning_en":"","page":1215}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":1215,"lines":[{"gurmukhi":"ਕਾਹੂ ਸਿਮਟਿ ਸੈਹਥੀ ਹਨੈ। ਏਕ ਸੁਭਟ ਮਨ ਮਾਹਿ ਨ ਗਨੈ।","roman":"Kaahoo simti saihthee hanai | ek subhat man maahi na ganai |","meaning_en":"","page":1215},{"gurmukhi":"ਦੇਖੈ ਸੁਰ ਬਿਬਾਨ ਚੜਿ ਸਾਰੇ। ਚਟਿਪਟ ਸੁਭਟ ਬਿਕਟ ਕਟਿ ਡਾਰੇ। ੨੬।","roman":"Dekhai sur bibaan chari saare | chatipat subhat bikat kati daare | 26 |","meaning_en":"","page":1215}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":1215,"lines":[{"gurmukhi":"ਗੀਧਨ ਕੋ ਮਨ ਭਯੋ ਅਨੰਦੰ। ਆਜੁ ਭਖੈ ਮਾਨਸ ਕੇ ਅੰਗੰ।","roman":"Geedhan ko man bhayo anandan | aaju bhakhai maanas ke angan |","meaning_en":"","page":1215},{"gurmukhi":"ਦਹਿਨੇ ਬਾਏ ਜੋਗਿਨਿ ਖੜੀ। ਲੈ ਪਾਤਰ ਸ੍ਰੋਨਤ ਕਹ ਅੜੀ। ੨੭।","roman":"Dahine baae jogini kharee | lai paatar sronat kah aree | 27 |","meaning_en":"","page":1215}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1215,"lines":[{"gurmukhi":"ਮਾਰੂ ਦੁਹੂੰ ਦਿਸਨ ਮੈ ਬਾਜੈ। ਦੁਹੂੰ ਓਰ ਸਸਤ੍ਰਨ ਭਟ ਸਾਜੈ।","roman":"Maaroo duhoon disan mai baajai | duhoon or sastran bhat saajai |","meaning_en":"","page":1215},{"gurmukhi":"ਊਪਰ ਗਿਧ ਸਾਲ ਮੰਡਰਾਹੀ। ਤਰੈ ਸੂਰਮਾ ਜੁਧ ਮਚਾਹੀ। ੨੮।","roman":"Oopar gidh saal mandraahee | tarai soormaa judh machaahee | 28 |","meaning_en":"","page":1215}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":1215},{"type":"verse","number":[29],"number_text":"੨੯।","page":1215,"lines":[{"gurmukhi":"ਬਾਲ ਕੋ ਰੂਪ ਅਨੂਪਮ ਹੇਰਿ ਚਹੂੰ ਦਿਸਿ ਤੇ ਨ੍ਰਿਪ ਚੌਪਿ ਚਲੇ।","roman":"Baal ko roop anoopam heri chahoon disi te nrip chaupi chale |","meaning_en":"","page":1215},{"gurmukhi":"ਗਜਰਾਜਨ ਬਾਜਨ ਕੇ ਅਸਵਾਰ ਰਥੀ ਰਥ ਪਾਇਕ ਜੋਰਿ ਭਲੇ।","roman":"Gajraajan baajan ke asvaar rathee rath paaik jori bhale |","meaning_en":"","page":1215},{"gurmukhi":"ਜਬ ਰਾਇ ਬਚਿਤ੍ਰ ਕ੍ਰਿਪਾਨ ਗਹੀ ਤਜਿ ਲਾਜ ਹਠੀ ਯੌ ਰਨ ਬਿਚਲੇ।","roman":"Jab raai bachitr kripaan gahee taji laaj hathee yau ran bichle |","meaning_en":"","page":1215},{"gurmukhi":"ਮਨੋ ਰਾਮ ਕੇ ਨਾਮ ਕਹੇ ਮੁਖ ਤੇ ਅਘ ਓਘਨ ਕੇ ਤ੍ਰਸਿ ਬ੍ਰਿੰਦ ਟਲੇ। ੨੯।","roman":"Mano raam ke naam kahe mukh te agh oghan ke trasi brind tale | 29 |","meaning_en":"","page":1215}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":1215,"lines":[{"gurmukhi":"ਕੋਪ ਪ੍ਰਚੰਡ ਭਰੇ ਮਨ ਮੈ ਭਟ ਚੌਪਿ ਚੜੇ ਚਹੂੰਘਾ ਚਪਿ ਧਾਏ।","roman":"Kop prachand bhare man mai bhat chaupi chare chahoonghaa chapi dhaae |","meaning_en":"","page":1215},{"gurmukhi":"ਕਾਢਿ ਕ੍ਰਿਪਾਨ ਲਈ ਬਲਵਾਨਨ ਤਾਨਿ ਕਮਾਨਨ ਬਾਨ ਚਲਾਏ।","roman":"Kaadhi kripaan laee balvaanan taani kamaanan baan chalaae |","meaning_en":"","page":1215},{"gurmukhi":"ਬੂੰਦਨ ਜ੍ਯੋ ਬਰਖੇ ਚਹੂੰ ਓਰਨ ਬੇਧਿ ਸਨਾਹਨ ਪਾਰ ਪਰਾਏ।","roman":"Boondan jyo barkhe chahoon oran bedhi sanaahan paar paraae |","meaning_en":"","page":1215},{"gurmukhi":"ਬੀਰਨ ਚੀਰ ਬਿਦੀਰਨ ਭੂਮਿ ਕੋ ਬਾਰਿ ਕੋ ਫਾਰਿ ਪਤਾਰ ਸਿਧਾਏ। ੩੦।","roman":"Beeran cheer bideeran bhoomi ko baari ko phaari pataar sidhaae | 30 |","meaning_en":"","page":1215}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1215},{"type":"verse","number":[31],"number_text":"੩੧।","page":1215,"lines":[{"gurmukhi":"ਚਟਪਟ ਸੁਭਟ ਬਿਕਟ ਕਟਿ ਗਏ। ਕੇਤੇ ਕਰੀ ਕਰਨ ਬਿਨੁ ਭਏ।","roman":"Chatpat subhat bikat kati gae | kete karee karan binu bhae |","meaning_en":"","page":1215},{"gurmukhi":"ਟੂਟੈ ਰਥ ਕੂਟੰ ਭਟ ਡਾਰੇ। ਨਾਚੇ ਭੂਤ ਪ੍ਰੇਤ ਮਤਵਾਰੇ। ੩੧।","roman":"Tootai rath kootan bhat daare | naache bhoot pret matvaare | 31 |","meaning_en":"","page":1215}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":1215,"lines":[{"gurmukhi":"ਮੁਨਿ ਨਾਰਦ ਕਹੂੰ ਬੇਨੁ ਬਜਾਵੈ। ਕਹੂੰ ਰੁਦ੍ਰ ਡਮਰੂ ਡਮਕਾਵੈ।","roman":"Muni naarad kahoon benu bajaavai | kahoon rudr damroo damkaavai |","meaning_en":"","page":1215},{"gurmukhi":"ਰੁਧਿਰ ਖਪਰ ਜੁਗਿਨ ਭਰਿ ਭਾਰੀ। ਮਾਰਹਿ ਭੂਤ ਪ੍ਰੇਤ ਕਿਲਕਾਰੀ। ੩੨।","roman":"Rudhir khapar jugin bhari bhaaree | maarhi bhoot pret kilkaaree | 32 |","meaning_en":"","page":1215}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":1215,"lines":[{"gurmukhi":"ਰਨ ਅਗੰਮ ਕੋਊ ਜਾਨ ਨ ਪਾਵੈ। ਡਹ ਡਹ ਡਹ ਸਿਵ ਡਮਰੁ ਬਜਾਵੈ।","roman":"Ran aganm ko'oo jaan na paavai | dah dah dah siv damru bajaavai |","meaning_en":"","page":1215},{"gurmukhi":"ਕਹ ਕਹ ਕਹੂੰ ਕਾਲਿਕਾ ਕਹਕੈ। ਜਾਨੁਕ ਧੁਜਾ ਕਾਲ ਕੀ ਲਹਕੈ।੩੩।","roman":"Kah kah kahoon kaalikaa kahkai | jaanuk dhujaa kaal kee lahkai | 33 |","meaning_en":"","page":1215}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":1215,"lines":[{"gurmukhi":"ਹਸਤ ਪਾਰਬਤੀ ਨੈਨ ਬਿਸਾਲਾ। ਨਾਚਤ ਭੂਪ ਪ੍ਰੇਤ ਬੈਤਾਲਾ।","roman":"Hasat paarabtee nain bisaalaa | naachat bhoop pret baitaalaa |","meaning_en":"","page":1215},{"gurmukhi":"ਕਹ ਕਹਾਟ ਕਹੂੰ ਕਾਲ ਸੁਨਾਵੈ। ਭੀਖਨ ਸੁਨੇ ਨਾਦ ਭੈ ਆਵੈ। ੩੪।","roman":"Kah kahaat kahoon kaal sunaavai | bheekhan sune naad bhai aavai | 34 |","meaning_en":"","page":1215}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":1217,"lines":[{"gurmukhi":"ਬਿਨੁ ਸੀਸਨ ਕੇਤਿਕ ਭਟ ਡੋਲਹਿ। ਕੇਤਿਨ ਮਾਰਿ ਮਾਰਿ ਕਰਿ ਬੋਲਹਿ।","roman":"Binu seesan ketik bhat dolhi | ketin maari maari kari bolhi |","meaning_en":"","page":1217},{"gurmukhi":"ਕਿਤੇ ਤਮਕਿ ਰਨ ਤੁਰੈ ਨਚਾਵੈ। ਜੂਝਿ ਕਿਤਕ ਜਮ ਲੋਕ ਸਿਧਾਵੈ। ੩੫।","roman":"Kite tamki ran turai nachaavai | joojhi kitak jam lok sidhaavai | 35 |","meaning_en":"","page":1217}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":1217,"lines":[{"gurmukhi":"ਕਟਿ ਕਟਿ ਪਰੇ ਸੁਭਟ ਛਿਤ ਭਾਰੇ। ਭੂਪ ਸੁਤਾ ਕਰਿ ਕੋਪ ਪਛਾਰੇ।","roman":"Kati kati pare subhat chhit bhaare | bhoop sutaa kari kop pachhaare |","meaning_en":"","page":1217},{"gurmukhi":"ਜਿਨ ਕੇ ਪਰੀ ਹਾਥ ਨਹਿ ਪ੍ਯਾਰੀ। ਬਿਨੁ ਮਾਰੇ ਹਨਿ ਮਰੇ ਕਟਾਰੀ। ੩੬।","roman":"Jin ke paree haath nahi pyaaree | binu maare hani mare kataaree | 36 |","meaning_en":"","page":1217}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1217},{"type":"verse","number":[37],"number_text":"੩੭।","page":1217,"lines":[{"gurmukhi":"ਮੋੜਤੇਸ ਅੰਬੇਰ ਪਤਿ ਅਮਿਤ ਸੈਨ ਲੈ ਸਾਥ।","roman":"Mortes anber pati amit sain lai saath |","meaning_en":"","page":1217},{"gurmukhi":"ਬਾਲ ਨਿਮਿਤਿ ਆਵਤ ਭਏ ਗਹੇ ਬਰਛਿਯੈ ਹਾਥ। ੩੭।","roman":"Baal nimiti aavat bhae gahe barchhiyai haath | 37 |","meaning_en":"","page":1217}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":1217,"lines":[{"gurmukhi":"ਬਿਕਟ ਸਿੰਘ ਅੰਬੇਰ ਪਤਿ ਅਮਿਟ ਸਿੰਘ ਤਿਹ ਨਾਮ।","roman":"Bikat singh anber pati amit singh tih naam |","meaning_en":"","page":1217},{"gurmukhi":"ਕਬਹੂੰ ਦਈ ਨ ਪੀਠ ਰਨ ਜੀਤੇ ਬਹੁ ਸੰਗ੍ਰਾਮ। ੩੮।","roman":"Kabhoon daee na peeth ran jeete bahu sangraam | 38 |","meaning_en":"","page":1217}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1217},{"type":"verse","number":[39],"number_text":"੩੯।","page":1217,"lines":[{"gurmukhi":"ਤੇ ਨ੍ਰਿਪ ਜੋਰਿ ਸੈਨ ਦ੍ਵੈ ਧਾਏ। ਭਾਤਿ ਭਾਤਿ ਬਾਜਿਤ੍ਰ ਬਜਾਏ।","roman":"Te nrip jori sain dvai dhaae | bhaati bhaati baajitr bajaae |","meaning_en":"","page":1217},{"gurmukhi":"ਰਾਜ ਸੁਤਾ ਜਬ ਨੈਨ ਨਿਹਾਰੇ। ਸੈਨਾ ਸਹਿਤ ਮਾਰ ਹੀ ਡਾਰੇ। ੩੯।","roman":"Raaj sutaa jab nain nihaare | sainaa sahit maar hee daare | 39 |","meaning_en":"","page":1217}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":1217,"lines":[{"gurmukhi":"ਜਬ ਅਬਲਾ ਨ੍ਰਿਪ ਦੋਊ ਸੰਘਾਰੇ। ਠਟਕੇ ਸੁਭਟ ਸਕਲ ਤਬ ਭਾਰੇ।","roman":"Jab ablaa nrip do'oo sanghaare | thatke subhat sakal tab bhaare |","meaning_en":"","page":1217},{"gurmukhi":"ਖੇਤ ਛਾਡਿ ਯਹ ਤਰੁਨਿ ਨ ਟਰਿਹੈ। ਸਭਹਿਨ ਕੋ ਪ੍ਰਾਨਨ ਬਿਨੁ ਕਰਿ ਹੈ। ੪੦।","roman":"Khet chhaadi yah taruni na tarihai | sabhhin ko praanan binu kari hai | 40 |","meaning_en":"","page":1217}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":1217,"lines":[{"gurmukhi":"ਬੂੰਦੀ ਨਾਥ ਰਣੁਤ ਕਟ ਧਾਯੋ। ਅਧਿਕ ਮਦੁਤ ਕਟ ਸਿੰਘ ਰਿਸਾਯੋ।","roman":"Boondee naath ranut kat dhaayo | adhik madut kat singh risaayo |","meaning_en":"","page":1217},{"gurmukhi":"ਨਾਥ ਉਜੈਨ ਜਿਸੇ ਜਗ ਕਹਈ। ਵਾ ਕਹਿ ਜੀਤੈ ਜਗ ਕੋ ਰਹਈ। ੪੧।","roman":"Naath ujain jise jag kahaee | vaa kahi jeetai jag ko rahaee | 41 |","meaning_en":"","page":1217}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":1217,"lines":[{"gurmukhi":"ਜਬ ਅਬਲਾ ਆਵਤ ਵਹੁ ਲਹੇ। ਹਾਥ ਹਥਯਾਰ ਆਪਨੇ ਗਹੇ।","roman":"Jab ablaa aavat vahu lahe | haath hathyaar aapne gahe |","meaning_en":"","page":1217},{"gurmukhi":"ਅਧਿਕ ਕੋਪ ਕਰਿ ਕੁਵਤਿ ਪ੍ਰਹਾਰੇ। ਛਿਨਿਕ ਬਿਖੈ ਦਲ ਸਹਿਤ ਸੰਘਾਰੇ। ੪੨।","roman":"Adhik kop kari kuvti prahaare | chhinik bikhai dal sahit sanghaare | 42 |","meaning_en":"","page":1217}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":1217,"lines":[{"gurmukhi":"ਗੰਗਾਂਦ੍ਰੀ ਜਮੁਨਾਂਦ੍ਰੀ ਹਠੇ। ਸਾਰਸ੍ਵਤੀ ਹ੍ਵੈ ਚਲੇ ਇਕਠੇ।","roman":"Gangaandree jamunaandree hathe | saarsvatee hvai chale ikthe |","meaning_en":"","page":1217},{"gurmukhi":"ਸਤੁਦ੍ਰਵਾਦਿ ਅਤਿ ਦ੍ਰਿੜ ਪਗ ਰੋਪੇ। ਬ੍ਯਾਹਾਦ੍ਰੀ ਸਿਗਰੇ ਮਿਲਿ ਕੋਪੇ। ੪੩।","roman":"Satudravaadi ati drir pag rope | byaahaadree sigre mili kope | 43 |","meaning_en":"","page":1217}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1217},{"type":"verse","number":[44],"number_text":"੪੪।","page":1217,"lines":[{"gurmukhi":"ਪਰਮ ਸਿੰਘ ਪੂਰੋ ਪੁਰਖ ਕਰਮ ਸਿੰਘ ਸੁਰ ਗ੍ਯਾਨ।","roman":"Param singh pooro purakh karam singh sur gyaan |","meaning_en":"","page":1217},{"gurmukhi":"ਧਰਮ ਸਿੰਘ ਹਾਠੋ ਹਠੀ ਅਮਿਤ ਜੁਧ ਕੀ ਖਾਨ। ੪੪।","roman":"Dharam singh haatho hathee amit judh kee khaan | 44 |","meaning_en":"","page":1217}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":1217,"lines":[{"gurmukhi":"ਅਮਰ ਸਿੰਘ ਅਰੁ ਅਚਲ ਸਿੰਘ ਮਨ ਮੈ ਕੋਪ ਬਢਾਇ।","roman":"Amar singh aru achal singh man mai kop badhaai |","meaning_en":"","page":1217},{"gurmukhi":"ਪਾਚੌ ਭੂਪ ਪਹਾਰਿਯੈ ਸਨਮੁਖਿ ਪਹੁਚੇ ਆਇ। ੪੫।","roman":"Paachau bhoop pahaariyai sanmukhi pahuche aai | 45 |","meaning_en":"","page":1217}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1217},{"type":"verse","number":[46],"number_text":"੪੬।","page":1217,"lines":[{"gurmukhi":"ਪਰਬਤੀਸ ਪਾਚੋ ਨ੍ਰਿਪ ਧਾਏ। ਖਸੀਯਾ ਅਧਿਕ ਸੰਗ ਲੈ ਆਏ।","roman":"Parabtees paacho nrip dhaae | khaseeyaa adhik sang lai aae |","meaning_en":"","page":1217},{"gurmukhi":"ਪਾਹਨ ਬ੍ਰਿਸਟਿ ਕੋਪ ਕਰਿ ਕਰੀ। ਮਾਰਿ ਮਾਰਿ ਮੁਖ ਤੇ ਉਚਰੀ। ੪੬।","roman":"Paahan bristi kop kari karee | maari maari mukh te uchree | 46 |","meaning_en":"","page":1217}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":1219,"lines":[{"gurmukhi":"ਦੁੰਦਭ ਢੋਲ ਦੁਹੂੰ ਦਿਸਿ ਬਾਜੇ। ਸਾਜੇ ਸਸਤ੍ਰ ਸੂਰਮਾ ਗਾਜੇ।","roman":"Dundabh dhol duhoon disi baaje | saaje sasatr soormaa gaaje |","meaning_en":"","page":1219},{"gurmukhi":"ਕੁਪਿ ਕੁਪਿ ਅਧਿਕ ਹ੍ਰਿਦਨ ਮੈ ਲਰੇ। ਕਟਿ ਕਟਿ ਮਰੇ ਬਰੰਗਨਿ ਬਰੇ। ੪੭।","roman":"Kupi kupi adhik hridan mai lare | kati kati mare barangni bare | 47 |","meaning_en":"","page":1219}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":1219,"lines":[{"gurmukhi":"ਭੂਪ ਪਾਚਉ ਬਾਨ ਚਲਾਵੈ। ਬਾਧੇ ਗੋਲ ਸਾਮੁਹੇ ਆਵੈ।","roman":"Bhoop paachau baan chalaavai | baadhe gol saamuhe aavai |","meaning_en":"","page":1219},{"gurmukhi":"ਤਬ ਬਚਿਤ੍ਰ ਦੇ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰੇ। ਛਿਨਿਕ ਬਿਖੈ ਸਕਲੇ ਹਨਿ ਡਾਰੇ। ੪੮।","roman":"Tab bachitr de sasatr prahaare | chhinik bikhai sakle hani daare | 48 |","meaning_en":"","page":1219}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":1219,"lines":[{"gurmukhi":"ਦੇਇ ਬਚਿਤ੍ਰ ਪਾਚ ਨ੍ਰਿਪ ਮਾਰੇ। ਔਰ ਸੁਭਟ ਚੁਨਿ ਚੁਨਿ ਹਨਿ ਡਾਰੇ।","roman":"Dei bachitr paach nrip maare | aur subhat chuni chuni hani daare |","meaning_en":"","page":1219},{"gurmukhi":"ਸਾਤ ਨ੍ਰਿਪਤਿ ਅਵਰੈ ਤਬ ਚਲੇ। ਜੋਧਾ ਜੋਰ ਜੁਧ ਕਰਿ ਭਲੇ। ੪੯।","roman":"Saat nripti avrai tab chale | jodhaa jor judh kari bhale | 49 |","meaning_en":"","page":1219}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":1219,"lines":[{"gurmukhi":"ਕਾਸਿ ਰਾਜ ਮਘਧੇਸ੍ਵਰ ਕੋਪੇ। ਅੰਗ ਬੰਗ ਰਾਜਨ ਪਗ ਰੋਪੇ।","roman":"Kaasi raaj maghdhesvar kope | ang bang raajan pag rope |","meaning_en":"","page":1219},{"gurmukhi":"ਔਰ ਕੁਲਿੰਗ ਦੇਸ ਪਤਿ ਧਾਯੋ। ਤ੍ਰਿਗਤਿ ਦੇਸ ਏਸ੍ਵਰ ਹੂੰ ਆਯੋ। ੫੦।","roman":"Aur kuling des pati dhaayo | trigti des esvar hoon aayo | 50 |","meaning_en":"","page":1219}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":1219,"lines":[{"gurmukhi":"ਰਾਜਾ ਕਾਮ ਰੂਪ ਕੋ ਧਾਯੋ। ਅਮਿਤ ਕਟਕ ਲੀਨੇ ਸੰਗ ਆਯੋ।","roman":"Raajaa kaam roop ko dhaayo | amit katak leene sang aayo |","meaning_en":"","page":1219},{"gurmukhi":"ਦਾਰੁਣ ਰਣ ਸੂਰਣ ਤਹ ਕਰਿਯੋ। ਰਵਿ ਸਸਿ ਚਕ੍ਯੋ ਇੰਦ੍ਰ ਥਰਹਰਿਯੋ। ੫੧।","roman":"Daarun ran sooran tah kariyo | ravi sasi chakyo indr tharahriyo | 51 |","meaning_en":"","page":1219}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":1219,"lines":[{"gurmukhi":"ਅੰਗ ਕਟੇ ਤਰਫੈ ਕਹੂੰ ਅੰਗਰੀ। ਬੀਰ ਪਰੇ ਉਛਰਤ ਕਹੂੰ ਟੰਗਰੀ।","roman":"Ang kate tarphai kahoon angree | beer pare uchhrat kahoon tangree |","meaning_en":"","page":1219},{"gurmukhi":"ਹਠਿ ਹਠਿ ਭਿਰੇ ਸੁਭਟ ਰਨ ਮਾਹੀ। ਜੰਬਕ ਗੀਧ ਮਾਸੁ ਲੈ ਜਾਹੀ। ੫੨।","roman":"Hathi hathi bhire subhat ran maahee | janbak geedh maasu lai jaahee | 52 |","meaning_en":"","page":1219}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":1219},{"type":"verse","number":[53],"number_text":"੫੩।","page":1219,"lines":[{"gurmukhi":"ਬਾਲ ਸੂਰਮਾ ਮਾਰੇ ਕੋਪ ਬਢਾਇ ਕੈ।","roman":"Baal soormaa maare kop badhaai kai |","meaning_en":"","page":1219},{"gurmukhi":"ਜੋ ਚਿਤੁ ਚਹੈ ਸੰਘਾਰੇ ਰਥਹਿ ਧਵਾਇ ਕੈ।","roman":"Jo chitu chahai sanghaare rathhi dhavaai kai |","meaning_en":"","page":1219},{"gurmukhi":"ਪੈਦਲ ਅਮਿਤ ਬਿਦਾਰੇ ਅਤਿ ਚਿਤ ਕੋਪ ਕਰਿ।","roman":"Paidal amit bidaare ati chit kop kari |","meaning_en":"","page":1219},{"gurmukhi":"ਹੋ ਰਥੀ ਗਜੀ ਹਨਿ ਡਾਰੇ ਸਸਤ੍ਰ ਅਨਿਕ ਪ੍ਰਹਰਿ। ੫੩।","roman":"Ho rathee gajee hani daare sasatr anik prahri | 53 |","meaning_en":"","page":1219}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1219},{"type":"verse","number":[54],"number_text":"੫੪।","page":1219,"lines":[{"gurmukhi":"ਸਪਤਾਵਤ ਨ੍ਰਿਪ ਬਾਲ ਨਿਹਾਰੇ। ਅਮਿਤ ਕੋਪ ਕਰਿ ਬਿਸਿਖ ਪ੍ਰਹਾਰੇ।","roman":"Saptaavat nrip baal nihaare | amit kop kari bisikh prahaare |","meaning_en":"","page":1219},{"gurmukhi":"ਸ੍ਯੰਦਨ ਸਹਿਤ ਸੂਤ ਸਭ ਘਾਏ। ਸੈਨ ਸਹਿਤ ਮ੍ਰਿਤ ਲੋਕ ਪਠਾਏ। ੫੪।","roman":"Syandan sahit soot sabh ghaae | sain sahit mrit lok pathaae | 54 |","meaning_en":"","page":1219}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":1219,"lines":[{"gurmukhi":"ਅਵਰ ਨ੍ਰਿਪਤ ਤਬ ਹੀ ਉਠਿ ਧਾਏ। ਬਾਧੇ ਗੋਲ ਸਾਮੁਹੇ ਆਏ।","roman":"Avar nripat tab hee uthi dhaae | baadhe gol saamuhe aae |","meaning_en":"","page":1219},{"gurmukhi":"ਦਸੌ ਦਿਸਨ ਕ੍ਰੁਧਿਤ ਹ੍ਵੈ ਢੂਕੇ। ਮਾਰੈ ਮਾਰ ਬਕ੍ਰ ਤੇ ਕੂਕੇ। ੫੫।","roman":"Dasau disan krudhit hvai dhooke | maarai maar bakr te kooke | 55 |","meaning_en":"","page":1219}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1219},{"type":"verse","number":[56],"number_text":"੫੬।","page":1219,"lines":[{"gurmukhi":"ਬੀਰ ਕੇਤੁ ਬਾਕੋ ਰਥੀ ਚਿਤ੍ਰ ਕੇਤੁ ਸੁਰ ਗ੍ਯਾਨ।","roman":"Beer ketu baako rathee chitr ketu sur gyaan |","meaning_en":"","page":1219},{"gurmukhi":"ਛਤ੍ਰ ਕੇਤੁ ਛਤ੍ਰੀ ਅਮਿਟ ਬਿਕਟ ਕੇਤੁ ਬਲਵਾਨ। ੫੬।","roman":"Chhatr ketu chhatree amit bikat ketu balvaan | 56 |","meaning_en":"","page":1219}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":1221,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਕੇਤੁ ਉਪਇੰਦ੍ਰ ਧੁਜ ਚਿਤ ਅਤਿ ਕੋਪ ਬਢਾਇ।","roman":"Indr ketu upaindr dhuj chit ati kop badhaai |","meaning_en":"","page":1221},{"gurmukhi":"ਗੀਧ ਕੇਤੁ ਦਾਨਵ ਸਹਿਤ ਤਹਾ ਪਹੂੰਚੇ ਆਇ। ੫੭।","roman":"Geedh ketu daanav sahit tahaa pahoonche aai | 57 |","meaning_en":"","page":1221}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":1221,"lines":[{"gurmukhi":"ਸਪਤ ਨ੍ਰਿਪਤਿ ਆਯੁਧ ਧਰੇ ਅਮਿਤ ਸੈਨ ਲੈ ਸਾਥ।","roman":"Sapat nripti aayudh dhare amit sain lai saath |","meaning_en":"","page":1221},{"gurmukhi":"ਧਾਇ ਪਰੇ ਨਾਹਿਨ ਡਰੇ ਕਢੇ ਬਢਾਰੀ ਹਾਥ। ੫੮।","roman":"Dhaai pare naahin dare kadhe badhaaree haath | 58 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1221},{"type":"verse","number":[59],"number_text":"੫੯।","page":1221,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਸੂਰਮਾ ਧਾਏ। ਜੋਰੇ ਸੈਨ ਕੁਅਰਿ ਢਿਗ ਆਏ।","roman":"Sasatr sanbhaari soormaa dhaae | jore sain kuari dhig aae |","meaning_en":"","page":1221},{"gurmukhi":"ਆਯੁਧ ਹਾਥ ਬਚਿਤ੍ਰ ਧਰੇ। ਅਮਿਤ ਸੁਭਟ ਪ੍ਰਾਨਨ ਬਿਨੁ ਕਰੇ। ੫੯।","roman":"Aayudh haath bachitr dhare | amit subhat praanan binu kare | 59 |","meaning_en":"","page":1221}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":1221,"lines":[{"gurmukhi":"ਬੀਰ ਕੇਤੁ ਕੋ ਮੂੰਡ ਉਤਾਰਿਯੋ। ਚਿਤ੍ਰ ਕੇਤੁ ਕਟਿ ਤੇ ਕਟ ਡਾਰਿਯੋ।","roman":"Beer ketu ko moond utaariyo | chitr ketu kati te kat daariyo |","meaning_en":"","page":1221},{"gurmukhi":"ਛਤ੍ਰ ਕੇਤੁ ਛਤ੍ਰੀ ਪੁਨਿ ਘਾਯੋ। ਬਿਕਟ ਕੇਤੁ ਮ੍ਰਿਤ ਲੋਕ ਪਠਾਯੋ। ੬੦।","roman":"Chhatr ketu chhatree puni ghaayo | bikat ketu mrit lok pathaayo | 60 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1221},{"type":"verse","number":[61],"number_text":"੬੧।","page":1221,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਕੇਤੁ ਉਪਇੰਦ੍ਰ ਧੁਜ ਦੋਨੋ ਹਨੇ ਰਿਸਾਇ।","roman":"Indr ketu upaindr dhuj dono hane risaai |","meaning_en":"","page":1221},{"gurmukhi":"ਗੀਧ ਕੇਤੁ ਦਾਨਵ ਦਿਯੈ ਜਮਪੁਰਿ ਬਹੁਰਿ ਪਠਾਇ। ੬੧।","roman":"Geedh ketu daanav diyai jampuri bahuri pathaai | 61 |","meaning_en":"","page":1221}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":1221,"lines":[{"gurmukhi":"ਸੈਨਾ ਸਤਹੂੰ ਨ੍ਰਿਪਨ ਕੀ ਕੋਪਿ ਭਰੀ ਅਰਰਾਇ।","roman":"Sainaa sathoon nripan kee kopi bharee arraai |","meaning_en":"","page":1221},{"gurmukhi":"ਤੇ ਬਾਲਾ ਤਬ ਹੀ ਦਏ ਮ੍ਰਿਤੁ ਕੇ ਲੋਕ ਪਠਾਇ। ੬੨।","roman":"Te baalaa tab hee dae mritu ke lok pathaai | 62 |","meaning_en":"","page":1221}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":1221,"lines":[{"gurmukhi":"ਸੁਮਤ ਕੇਤੁ ਸੂਰਾ ਬਡੋ ਸਮਰ ਸਿੰਘ ਲੈ ਸੰਗ।","roman":"Sumat ketu sooraa bado samar singh lai sang |","meaning_en":"","page":1221},{"gurmukhi":"ਬ੍ਰਹਮ ਕੇਤੁ ਲੈ ਦਲ ਚਲਾ ਉਮਡਿ ਚਲੀ ਜਨੁ ਗੰਗ। ੬੩।","roman":"Braham ketu lai dal chalaa umdi chalee janu gang | 63 |","meaning_en":"","page":1221}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":1221,"lines":[{"gurmukhi":"ਤਾਲ ਕੇਤੁ ਖਟਬਕ੍ਰ ਧੁਜ ਜੋਧਾ ਹੁਤੇ ਬਿਸੇਖ।","roman":"Taal ketu khatbakr dhuj jodhaa hute bisekh |","meaning_en":"","page":1221},{"gurmukhi":"ਸੋ ਯਾ ਪਰ ਆਵਤ ਭਏ ਕਿਯੈ ਕਾਲ ਕੋ ਭੇਖ। ੬੪।","roman":"So yaa par aavat bhae kiyai kaal ko bhekh | 64 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1221},{"type":"verse","number":[65],"number_text":"੬੫।","page":1221,"lines":[{"gurmukhi":"ਦਾਨਵ ਗੀਧ ਕੇਤੁ ਕੋ ਭ੍ਰਾਤਾ। ਕਾਕ ਕੇਤੁ ਤਿਹੂੰ ਲੋਕ ਬਿਖ੍ਯਾਤਾ।","roman":"Daanav geedh ketu ko bhraataa | kaak ketu tihoon lok bikhyaataa |","meaning_en":"","page":1221},{"gurmukhi":"ਕ੍ਰੂਰ ਕੇਤੁ ਦਾਨਵ ਇਕ ਧਾਯੋ। ਲੀਨੇ ਅਮਿਤ ਦੈਤ ਦਲ ਆਯੋ। ੬੫।","roman":"Kroor ketu daanav ik dhaayo | leene amit dait dal aayo | 65 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":1221},{"type":"verse","number":[66],"number_text":"੬੬।","page":1221,"lines":[{"gurmukhi":"ਕਾਕ ਧੁਜਾ ਕਰਿ ਕੋਪ ਤਹੀ ਛਿਨ ਆਨਿ ਪਰਿਯੋ ਕਰਵਾਰ ਨਿਕਾਰੇ।","roman":"Kaak dhujaa kari kop tahee chhin aani pariyo karvaar nikaare |","meaning_en":"","page":1221},{"gurmukhi":"ਸਿੰਘ ਸਲਾ ਸਰਦੂਲ ਸਿਲੀ ਮੁਖ ਸਾਲ ਤਮਾਲ ਹਨੇ ਅਹਿ ਕਾਰੇ।","roman":"Singh salaa sardool silee mukh saal tamaal hane ahi kaare |","meaning_en":"","page":1221},{"gurmukhi":"ਸ੍ਵਾਨ ਸ੍ਰਿੰਗਾਲ ਸੁਰਾਂਤਕ ਸੀਸ ਧੁਜਾ ਰਥ ਨਾਗ ਧਰਾਧਰ ਭਾਰੇ।","roman":"Svaan sringaal suraantak sees dhujaa rath naag dharaadhar bhaare |","meaning_en":"","page":1221},{"gurmukhi":"ਯੌ ਬਰਖੇ ਨਭ ਤੇ ਹਰਖੇ ਰਿਪੁ ਆਨਿ ਦਸੋ ਦਿਸਿ ਤੇ ਭਭਕਾਰੇ। ੬੬।","roman":"Yau barkhe nabh te harkhe ripu aani daso disi te bhabhkaare | 66 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1221},{"type":"verse","number":[67],"number_text":"੬੭।","page":1221,"lines":[{"gurmukhi":"ਮਾਯਾ ਦੈਤ ਪਸਾਰਿ ਕੈ ਪੁਨਿ ਬੋਲਾ ਇਮਿ ਬੈਨ।","roman":"Maayaa dait pasaari kai puni bolaa imi bain |","meaning_en":"","page":1221},{"gurmukhi":"ਜੁਧੁ ਸੁਯੰਬਰ ਜੀਤਿ ਤੁਹਿ ਲੈ ਜੈਹੌ ਨਿਜੁ ਐਨ। ੬੭।","roman":"Judhu suyanbar jeeti tuhi lai jaihau niju ain | 67 |","meaning_en":"","page":1221}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":1223},{"type":"verse","number":[68],"number_text":"੬੮।","page":1223,"lines":[{"gurmukhi":"ਰਾਜ ਸੁਤਾ ਕਰਿ ਕੋਪ ਤਿਹੀ ਛਿਨ ਸਾਮੁਹਿ ਹ੍ਵੈ ਹਥਿਯਾਰ ਗਹੇ।","roman":"Raaj sutaa kari kop tihee chhin saamuhi hvai hathiyaar gahe |","meaning_en":"","page":1223},{"gurmukhi":"ਬਲਵਾਨ ਕਮਾਨ ਕੋ ਤਾਨਿ ਹਨੇ ਕਬਿ ਰਾਮ ਭਨੈ ਚਿਤ ਮੈ ਜੁ ਚਹੇ।","roman":"Balvaan kamaan ko taani hane kabi raam bhanai chit mai ju chahe |","meaning_en":"","page":1223},{"gurmukhi":"ਸਰ ਸੂਰ ਦਇੰਤਨ ਕੇ ਤਨ ਮੈ ਇਹ ਭਾਤਿ ਲਗੇ ਨਹਿ ਜਾਤ ਕਹੇ।","roman":"Sar soor daintan ke tan mai ih bhaati lage nahi jaat kahe |","meaning_en":"","page":1223},{"gurmukhi":"ਮਨੋ ਇੰਦ੍ਰ ਕੇ ਬਾਗ ਅਸੋਕ ਬਿਖੈ ਫੁਲਵਾਰਿਨ ਕੇ ਫਲ ਫੂਲ ਰਹੇ। ੬੮।","roman":"Mano indr ke baag asok bikhai phulvaarin ke phal phool rahe | 68 |","meaning_en":"","page":1223}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":1223,"lines":[{"gurmukhi":"ਕਾਢਿ ਕ੍ਰਿਪਾਨ ਮਹਾ ਕੁਪਿ ਕੈ ਭਟ ਕੂਦਿ ਪਰੇ ਸਰਦਾਰ ਕਰੋਰੇ।","roman":"Kaadhi kripaan mahaa kupi kai bhat koodi pare sardaar karore |","meaning_en":"","page":1223},{"gurmukhi":"ਬਾਲ ਹਨੇ ਬਲਵਾਨ ਘਨੇ ਇਕ ਫਾਸਿਨ ਸੌ ਗਹਿ ਕੈ ਝਕਝੋਰੇ।","roman":"Baal hane balvaan ghane ik phaasin sau gahi kai jhakjhore |","meaning_en":"","page":1223},{"gurmukhi":"ਸਾਜ ਪਰੇ ਕਹੂੰ ਤਾਜ ਗਿਰੇ ਗਜਰਾਜ ਗਿਰੇ ਛਿਤ ਪੈ ਸਿਰ ਤੋਰੇ।","roman":"Saaj pare kahoon taaj gire gajraaj gire chhit pai sir tore |","meaning_en":"","page":1223},{"gurmukhi":"ਲੁਟੇ ਰਥੀ ਰਥ ਫੂਟੇ ਕਹੂੰ ਬਿਨੁ ਸ੍ਵਾਰ ਫਿਰੈ ਹਿਨਨਾਵਤ ਘੋਰੇ। ੬੯।","roman":"Lute rathee rath phoote kahoon binu svaar phirai hinnaavat ghore | 69 |","meaning_en":"","page":1223}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1223},{"type":"verse","number":[70],"number_text":"੭੦।","page":1223,"lines":[{"gurmukhi":"ਜੇ ਭਟ ਅਮਿਤ ਕੋਪ ਕਰਿ ਧਾਏ। ਤੇ ਬਿਨੁ ਤਨ ਹ੍ਵੈ ਸੁਰਗ ਸਿਧਾਏ।","roman":"Je bhat amit kop kari dhaae | te binu tan hvai surag sidhaae |","meaning_en":"","page":1223},{"gurmukhi":"ਚਟਪਟ ਬਿਕਟ ਪਲਟਿ ਜੇ ਲਰੇ। ਕਟਿ ਕਟਿ ਮਰੇ ਬਰੰਗਨਿਨ ਬਰੇ। ੭੦।","roman":"Chatpat bikat palti je lare | kati kati mare barangnin bare | 70 |","meaning_en":"","page":1223}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":1223,"lines":[{"gurmukhi":"ਜੇ ਭਟ ਬਿਮੁਖਾਹਵ ਹ੍ਵੈ ਮੂਏ। ਇਤ ਕੇ ਭਏ ਨ ਉਤ ਕੇ ਹੂਏ।","roman":"Je bhat bimukhaahav hvai mooe | it ke bhae na ut ke hooe |","meaning_en":"","page":1223},{"gurmukhi":"ਗਰਜਿ ਪ੍ਰਾਨ ਬੀਰਨ ਜਿਨ ਦਏ। ਦੈ ਦੁੰਦਭੀ ਸ੍ਵਰਗ ਜਨੁ ਗਏ। ੭੧।","roman":"Garji praan beeran jin dae | dai dundbhee svarag janu gae | 71 |","meaning_en":"","page":1223}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1223},{"type":"verse","number":[72],"number_text":"੭੨।","page":1223,"lines":[{"gurmukhi":"ਜਿਨ ਇਸਤ੍ਰਿਨ ਜਰਿ ਅਗਨਿ ਮੈ ਪ੍ਰਾਨ ਆਪਨੇ ਦੀਨ।","roman":"Jin istrin jari agni mai praan aapne deen |","meaning_en":"","page":1223},{"gurmukhi":"ਝਗਰਿ ਬਰੰਗਨਿਨ ਤੇ ਤਹਾ ਛੀਨਿ ਪਤਿਨ ਕਹ ਲੀਨ। ੭੨।","roman":"Jhagri barangnin te tahaa chheeni patin kah leen | 72 |","meaning_en":"","page":1223}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1223},{"type":"verse","number":[73],"number_text":"੭੩।","page":1223,"lines":[{"gurmukhi":"ਐਸੇ ਬਾਲ ਬੀਰ ਬਹੁ ਮਾਰੇ। ਸੁਮਤਿ ਸਿੰਘ ਆਦਿਕ ਹਨਿ ਡਾਰੇ।","roman":"Aise baal beer bahu maare | sumti singh aadik hani daare |","meaning_en":"","page":1223},{"gurmukhi":"ਸਮਰ ਸੈਨ ਰਾਜਾ ਪੁਨਿ ਹਯੋ। ਤਾਲ ਕੇਤੁ ਮ੍ਰਿਤ ਲੋਕ ਪਠਯੋ। ੭੩।","roman":"Samar sain raajaa puni hayo | taal ketu mrit lok pathyo | 73 |","meaning_en":"","page":1223}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":1223,"lines":[{"gurmukhi":"ਬ੍ਰਹਮ ਕੇਤੁ ਕਹ ਪੁਨਿ ਹਨਿ ਦੀਨੋ। ਕਾਰਤਿਕੇਯ ਧੁਜ ਕੋ ਬਧ ਕੀਨੋ।","roman":"Braham ketu kah puni hani deeno | kaartikey dhuj ko badh keeno |","meaning_en":"","page":1223,"flags":[{"code":"ੋੇ","reason":"ੋ and ੇ typed on one letter; one covers the other, printed as ੋ"}]},{"gurmukhi":"ਕ੍ਰੂਰ ਕੇਤੁ ਦਾਨਵ ਤਬ ਧਾਯੋ। ਤੁਮਲ ਜੁਧ ਤਿਹ ਠੌਰ ਮਚਾਯੋ। ੭੪।","roman":"Kroor ketu daanav tab dhaayo | tumal judh tih thaur machaayo | 74 |","meaning_en":"","page":1223}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":1223,"lines":[{"gurmukhi":"ਕੌਲ ਕੇਤੁ ਦਾਨਵ ਉਠਿ ਧਾਯੋ। ਕਮਠ ਕੇਤੁ ਚਿਤ ਅਧਿਕ ਰਿਸਾਯੋ।","roman":"Kaul ketu daanav uthi dhaayo | kamath ketu chit adhik risaayo |","meaning_en":"","page":1223},{"gurmukhi":"ਕੇਤੁ ਉਲੂਕ ਚਲਾ ਦਲ ਲੈ ਕੈ। ਕੁਤਿਸਿਤ ਕੇਤੁ ਕ੍ਰੋਧ ਤਨ ਤੈ ਕੈ। ੭੫।","roman":"Ketu ulook chalaa dal lai kai | kutisit ketu krodh tan tai kai | 75 |","meaning_en":"","page":1223}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":1223,"lines":[{"gurmukhi":"ਕੌਲ ਕੇਤੁ ਤ੍ਰਿਯ ਤਬੈ ਸੰਘਾਰਾ। ਕੁਤਿਸਿਤ ਕੇਤੁ ਮਾਰ ਹੀ ਡਾਰਾ।","roman":"Kaul ketu triy tabai sanghaaraa | kutisit ketu maar hee daaraa |","meaning_en":"","page":1223},{"gurmukhi":"ਕਛਪ ਕੇਤੁ ਗਦਾ ਗਹਿ ਘਾਯੋ। ਕੇਤੁ ਲੂਕ ਮ੍ਰਿਤ ਲੋਕ ਪਠਾਯੋ। ੭੬।","roman":"Kachhap ketu gadaa gahi ghaayo | ketu look mrit lok pathaayo | 76 |","meaning_en":"","page":1223}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":1225,"lines":[{"gurmukhi":"ਜਾ ਤਨ ਬਾਲ ਗਦਾ ਕੀ ਮਾਰੈ। ਏਕੈ ਘਾਇ ਚੌਥਿ ਸਿਰ ਡਾਰੈ।","roman":"Jaa tan baal gadaa kee maarai | ekai ghaai chauthi sir daarai |","meaning_en":"","page":1225},{"gurmukhi":"ਜਾ ਕੇਤਕਿ ਮਾਰ ਤਨ ਬਾਨਾ। ਕਰੈ ਬੀਰ ਜਮਪੁਰੀ ਪਯਾਨਾ। ੭੭।","roman":"Jaa ketki maar tan baanaa | karai beer jampuree payaanaa | 77 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1225},{"type":"verse","number":[78],"number_text":"੭੮।","page":1225,"lines":[{"gurmukhi":"ਤਾ ਕੋ ਜੁਧੁ ਬਿਲੋਕਿ ਕਰਿ ਕਵਨ ਸੁਭਟ ਠਹਰਾਇ।","roman":"Taa ko judhu biloki kari kavan subhat thahraai |","meaning_en":"","page":1225},{"gurmukhi":"ਜੋ ਸਮੁਹੈ ਆਵਤ ਭਯਾ ਜਮਪੁਰ ਦਿਯਾ ਪਠਾਇ। ੭੮।","roman":"Jo samuhai aavat bhayaa jampur diyaa pathaai | 78 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":1225},{"type":"verse","number":[79],"number_text":"੭੯।","page":1225,"lines":[{"gurmukhi":"ਕੋਪ ਅਨੇਕ ਭਰੇ ਅਮਰਾਰਦਨ ਆਨਿ ਪਰੈ ਕਰਵਾਰਿ ਉਘਾਰੇ।","roman":"Kop anek bhare amraardan aani parai karvaari ughaare |","meaning_en":"","page":1225},{"gurmukhi":"ਪਟਿਸ ਲੋਹਹਥੀ ਪਰਸੇ ਅਮਿਤਾਯੁਧ ਲੈ ਕਰਿ ਕੋਪ ਪ੍ਰਹਾਰੇ।","roman":"Patis lohahthee parse amitaayudh lai kari kop prahaare |","meaning_en":"","page":1225},{"gurmukhi":"ਨਾਰਿ ਸੰਭਾਰਿ ਹਥਯਾਰ ਸੁਰਾਰਿ ਹਕਾਰਿ ਹਨੇ ਨਹਿ ਜਾਤ ਬਿਚਾਰੇ।","roman":"Naari sanbhaari hathyaar suraari hakaari hane nahi jaat bichaare |","meaning_en":"","page":1225},{"gurmukhi":"ਖੇਲਿ ਬਸੰਤ ਬਡੇ ਖਿਲਵਾਰ ਮਨੋ ਮਦ ਚਾਖਿ ਗਿਰੇ ਮਤਵਾਰੇ। ੭੯।","roman":"Kheli basant bade khilvaar mano mad chaakhi gire matvaare | 79 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1225},{"type":"verse","number":[80],"number_text":"੮੦।","page":1225,"lines":[{"gurmukhi":"ਹੈ ਗੈ ਰਥੀ ਬਾਜੀ ਘਨੇ ਜੋਧਾ ਹਨੇ ਅਨੇਕ।","roman":"Hai gai rathee baajee ghane jodhaa hane anek |","meaning_en":"","page":1225},{"gurmukhi":"ਜੀਤਿ ਸੁਯੰਬਰ ਰਨ ਰਹੀ ਭੂਪਤਿ ਬਚਾ ਨ ਏਕ। ੮੦।","roman":"Jeeti suyanbar ran rahee bhoopti bachaa na ek | 80 |","meaning_en":"","page":1225}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":1225,"lines":[{"gurmukhi":"ਬਾਜਨ ਕੀ ਬਾਜੀ ਪਰੀ ਬਾਜਨ ਬਜੇ ਅਨੇਕ।","roman":"Baajan kee baajee paree baajan baje anek |","meaning_en":"","page":1225},{"gurmukhi":"ਬਿਸਿਖ ਬਹੁਤ ਬਰਸੇ ਤਹਾ ਬਚਾ ਨ ਬਾਜੀ ਏਕ। ੮੧।","roman":"Bisikh bahut barse tahaa bachaa na baajee ek | 81 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1225},{"type":"verse","number":[82],"number_text":"੮੨।","page":1225,"lines":[{"gurmukhi":"ਦੈਤ ਦਏ ਜਮ ਧਾਮ ਪਠਾਈ। ਬਾਰੀ ਸੁਭਟ ਸਿੰਘ ਕੀ ਆਈ।","roman":"Dait dae jam dhaam pathaaee | baaree subhat singh kee aaee |","meaning_en":"","page":1225},{"gurmukhi":"ਤਿਹ ਤ੍ਰਿਯ ਕਹਾ ਆਇ ਤੁਮ ਲਰੋ। ਕੈ ਅਬ ਹਾਰਿ ਮਾਨ ਮੁਹਿ ਬਰੋ। ੮੨।","roman":"Tih triy kahaa aai tum laro | kai ab haari maan muhi baro | 82 |","meaning_en":"","page":1225}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":1225,"lines":[{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਜਬ ਯੌ ਸੁਨਿ ਪਾਯੋ। ਅਧਿਕ ਚਿਤ ਮੈ ਕੋਪ ਬਢਾਯੋ।","roman":"Subhat singh jab yau suni paayo | adhik chit mai kop badhaayo |","meaning_en":"","page":1225},{"gurmukhi":"ਮੈ ਕਾ ਜੁਧ ਤ੍ਰਿਯਾ ਤੇ ਡਰਿਹੋ। ਯਾ ਕੋ ਤ੍ਰਾਸ ਮਾਨਿ ਯਹ ਬਰਿਹੋ। ੮੩।","roman":"Mai kaa judh triyaa te dariho | yaa ko traas maani yah bariho | 83 |","meaning_en":"","page":1225}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":1225,"lines":[{"gurmukhi":"ਕਹੂੰ ਮਤਿ ਗੈਵਰ ਗਰਜਾਹੀ। ਕਹੂੰ ਪਾਖਰੇ ਹੈ ਹਿਂਹਨਾਹੀ।","roman":"Kahoon mati gaivar garjaahee | kahoon paakhre hai hinhnaahee |","meaning_en":"","page":1225},{"gurmukhi":"ਸਸਤ੍ਰ ਕਵਚ ਸੂਰਾ ਕਹੂੰ ਕਸੈ। ਜੁਗਿਨ ਰੁਧਿਰ ਖਪਰ ਭਰ ਹਸੈ। ੮੪।","roman":"Sasatr kavach sooraa kahoon kasai | jugin rudhir khapar bhar hasai | 84 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":1225},{"type":"verse","number":[85],"number_text":"੮੫।","page":1225,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਸੁਭਟੇਸ ਬਡੋ ਦਲੁ ਲੈ ਉਮਡਿਯੋ ਗਹਿ ਕੈ ਕਰਿ ਆਯੁਧ ਬਾਕੇ।","roman":"Sree subhtes bado dalu lai umdiyo gahi kai kari aayudh baake |","meaning_en":"","page":1225},{"gurmukhi":"ਬੀਰ ਹਠੀ ਕਵਚੀ ਖੜਗੀ ਪਰਸੀਸ ਭਈ ਸਰਦਾਰ ਨਿਸਾਕੇ।","roman":"Beer hathee kavchee khargee parsees bhaee sardaar nisaake |","meaning_en":"","page":1225},{"gurmukhi":"ਏਕ ਟਰੇ ਇਕ ਆਨ ਅਰੇ ਇਕ ਜੂਝਿ ਗਿਰੇ ਬ੍ਰਿਣ ਖਾਇ ਤ੍ਰਿਯਾ ਕੇ।","roman":"Ek tare ik aan are ik joojhi gire brin khaai triyaa ke |","meaning_en":"","page":1225},{"gurmukhi":"ਛਾਰ ਚੜਾਇ ਕੈ ਅੰਗ ਮਲੰਗ ਰਹੇ ਮਨੌ ਸੋਇ ਪਿਯੇ ਬਿਜਯਾ ਕੇ। ੮੫।","roman":"Chhaar charaai kai ang malang rahe manau soi piye bijyaa ke | 85 |","meaning_en":"","page":1225}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1227},{"type":"verse","number":[86],"number_text":"੮੬।","page":1227,"lines":[{"gurmukhi":"ਐਸੋ ਬੀਰ ਖੇਤ ਤਹ ਪਰਿਯੋ। ਏਕ ਸੁਭਟ ਜੀਵਤ ਨ ਉਬਰਿਯੋ।","roman":"Aiso beer khet tah pariyo | ek subhat jeevat na ubriyo |","meaning_en":"","page":1227},{"gurmukhi":"ਦਸ ਹਜਾਰ ਮਾਤੇ ਗਜ ਮਾਰੇ। ਬੀਸ ਹਜਾਰ ਬਰ ਬਾਜ ਬਿਦਾਰੇ। ੮੬।","roman":"Das hajaar maate gaj maare | bees hajaar bar baaj bidaare | 86 |","meaning_en":"","page":1227}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":1227,"lines":[{"gurmukhi":"ਤੀਸ ਐਤ ਪੈਦਲ ਕਹ ਮਾਰਿਯੋ। ਤੇਇਸ ਲਛ ਰਥ ਹਨਿ ਡਾਰਿਯੋ।","roman":"Tees ait paidal kah maariyo | teis lachh rath hani daariyo |","meaning_en":"","page":1227},{"gurmukhi":"ਦ੍ਵਾਦਸ ਲਛ ਰਥੀ ਅਤਿ ਮਾਰਿਸ। ਮਹਾਰਥੀ ਅਨਗਨਤ ਸੰਘਾਰਸਿ।੮੭।","roman":"Dvaadas lachh rathee ati maaris | mahaarthee anagnat sanghaarsi | 87 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1227},{"type":"verse","number":[88],"number_text":"੮੮।","page":1227,"lines":[{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਤਨਹਾ ਬਚਾ ਸਾਥੀ ਰਹਾ ਨ ਏਕ।","roman":"Subhat singh tanhaa bachaa saathee rahaa na ek |","meaning_en":"","page":1227},{"gurmukhi":"ਹੈ ਗੈ ਰਥ ਬਾਜੀ ਘਨੇ ਰਥ ਕਟਿ ਗਏ ਅਨੇਕ। ੮੮।","roman":"Hai gai rath baajee ghane rath kati gae anek | 88 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1227},{"type":"verse","number":[89],"number_text":"੮੯।","page":1227,"lines":[{"gurmukhi":"ਦੁੰਦ ਜੁਧ ਤ੍ਰਿਯ ਪਤਿਹ ਮਚਾਯੋ। ਨਿਰਖਨ ਦਿਨਿਸ ਨਿਸਿਸ ਰਨ ਆਯੋ।","roman":"Dund judh triy patih machaayo | nirkhan dinis nisis ran aayo |","meaning_en":"","page":1227},{"gurmukhi":"ਬ੍ਰਹਮਾ ਚੜੇ ਹੰਸ ਪਰ ਆਏ। ਪੰਚ ਬਦਨ ਹੂੰ ਤਹਾ ਸੁਹਾਏ। ੮੯।","roman":"Brahmaa chare hans par aae | panch badan hoon tahaa suhaae | 89 |","meaning_en":"","page":1227}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":1227,"lines":[{"gurmukhi":"ਤ੍ਰਿਯ ਕੋਮਲ ਪਿਯ ਬਾਨ ਪ੍ਰਹਾਰੈ। ਜਿਯ ਤੇ ਤਾਹਿ ਮਾਰਿ ਨਹਿ ਡਾਰੈ।","roman":"Triy komal piy baan prahaarai | jiy te taahi maari nahi daarai |","meaning_en":"","page":1227},{"gurmukhi":"ਲਗੇ ਬਿਸਿਖ ਕੇ ਜਿਨ ਪਤਿ ਮਰੈ। ਮੁਹਿ ਪੈਠਬ ਪਾਵਕ ਮਹਿ ਪਰੈ। ੯੦।","roman":"Lage bisikh ke jin pati marai | muhi paithab paavak mahi parai | 90 |","meaning_en":"","page":1227}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":1227,"lines":[{"gurmukhi":"ਚਾਰ ਪਹਰ ਨਿਜ ਪਤਿ ਸੋ ਲਰੀ। ਦੁਹੂੰਅਨ ਬਿਸਿਖ ਬ੍ਰਿਸਟਿ ਬਹੁ ਕਰੀ।","roman":"Chaar pahar nij pati so laree | duhoonan bisikh bristi bahu karee |","meaning_en":"","page":1227},{"gurmukhi":"ਤਬ ਲੋ ਸੂਰ ਅਸਤ ਹ੍ਵੈ ਗਯੋ। ਪ੍ਰਾਚੀ ਦਿਸਾ ਚੰਦ੍ਰ ਪ੍ਰਗਟ੍ਯੋ। ੯੧।","roman":"Tab lo soor asat hvai gayo | praachee disaa chandr pragtyo | 91 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1227},{"type":"verse","number":[92],"number_text":"੯੨।","page":1227,"lines":[{"gurmukhi":"ਹਕਾਹਕੀ ਆਹਵ ਭਯੋ ਰਹਿਯੋ ਸੁਭਟ ਕੋਊ ਨਾਹਿ।","roman":"Hakaahkee aahav bhayo rahiyo subhat ko'oo naahi |","meaning_en":"","page":1227},{"gurmukhi":"ਜੁਧ ਕਰਤ ਅਤਿ ਥਕਤ ਭੇ ਰਹਤ ਭਏ ਰਨ ਮਾਹਿ। ੯੨।","roman":"Judh karat ati thakat bhe rahat bhae ran maahi | 92 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1227},{"type":"verse","number":[93],"number_text":"੯੩।","page":1227,"lines":[{"gurmukhi":"ਲਗੇ ਬ੍ਰਿਨਨ ਕੇ ਘਾਇਲ ਭਏ। ਅਤਿ ਲਰਿ ਅਧਿਕ ਸ੍ਰਮਤ ਹ੍ਵੈ ਗਏ।","roman":"Lage brinan ke ghaail bhae | ati lari adhik sramat hvai gae |","meaning_en":"","page":1227},{"gurmukhi":"ਆਹਵ ਬਿਖੈ ਗਿਰੇ ਬਿਸੰਭਾਰੀ। ਕਰ ਤੇ ਕਿਨਹੂੰ ਕ੍ਰਿਪਾਨ ਨ ਡਾਰੀ। ੯੩।","roman":"Aahav bikhai gire bisanbhaaree | kar te kinhoon kripaan na daaree | 93 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1227},{"type":"verse","number":[94],"number_text":"੯੪।","page":1227,"lines":[{"gurmukhi":"ਪ੍ਰੇਤ ਨਚਹਿ ਜੁਗਨਿ ਹਸਹਿ ਜੰਬੁਕ ਗੀਧ ਫਿਰਾਹਿ।","roman":"Pret nachhi jugni hashi janbuk geedh phiraahi |","meaning_en":"","page":1227},{"gurmukhi":"ਨਿਸਿ ਸਿਗਰੀ ਮੁਰਛਿਤ ਰਹੇ ਦੁਹੁੰ ਰਹੀ ਸੁਧਿ ਨਾਹਿ। ੯੪।","roman":"Nisi sigree murchhit rahe duhun rahee sudhi naahi | 94 |","meaning_en":"","page":1227}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":1227,"lines":[{"gurmukhi":"ਪ੍ਰਾਚੀ ਦਿਸਿ ਰਵਿ ਪ੍ਰਗਟਿਯਾ ਭਈ ਚੰਦ੍ਰ ਕੀ ਹਾਨ।","roman":"Praachee disi ravi pragtiyaa bhaee chandr kee haan |","meaning_en":"","page":1227},{"gurmukhi":"ਪੁਨਿ ਪਤਿ ਤ੍ਰਿਯ ਰਨ ਕੋ ਉਠੇ ਅਧਿਕ ਕੋਪ ਮਨ ਠਾਨਿ। ੯੫।","roman":"Puni pati triy ran ko uthe adhik kop man thaani | 95 |","meaning_en":"","page":1227}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1227},{"type":"verse","number":[96],"number_text":"੯੬।","page":1227,"lines":[{"gurmukhi":"ਆਠ ਜਾਮ ਦੋਊ ਉਠਿ ਕਰਿ ਲਰੇ। ਟੂਕਤ ਤਨੁਤ੍ਰਾਣਨ ਕੇ ਝਰੇ।","roman":"Aath jaam do'oo uthi kari lare | tookat tanutraanan ke jhare |","meaning_en":"","page":1227},{"gurmukhi":"ਅਧਿਕ ਲਰਾਈ ਦੁਹੂੰ ਮਚਈ। ਅਥ੍ਯੋ ਸੂਰ ਰੈਨ ਹ੍ਵੈ ਗਈ। ੯੬।","roman":"Adhik laraaee duhoon machaee | athyo soor rain hvai gaee | 96 |","meaning_en":"","page":1227}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":1229,"lines":[{"gurmukhi":"ਚਾਰਿ ਬਾਜ ਬਿਸਿਖਨ ਤ੍ਰਿਯ ਮਾਰੇ। ਰਥ ਕੇ ਕਾਟਿ ਦੋਊ ਚਕ ਡਾਰੇ।","roman":"Chaari baaj bisikhan triy maare | rath ke kaati do'oo chak daare |","meaning_en":"","page":1229},{"gurmukhi":"ਨਾਥ ਧੁਜਾ ਕਟਿ ਭੂਮਿ ਗਿਰਾਈ। ਸੂਤਿ ਦਿਯਾ ਜਮਲੋਕ ਪਠਾਈ। ੯੭।","roman":"Naath dhujaa kati bhoomi giraaee | sooti diyaa jamlok pathaaee | 97 |","meaning_en":"","page":1229}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":1229,"lines":[{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਕਹ ਪੁਨਿ ਸਰ ਮਾਰਿਯੋ। ਮੂਰਛਿਤ ਕਰਿ ਪ੍ਰਿਥਵੀ ਪਰ ਡਾਰਿਯੋ।","roman":"Subhat singh kah puni sar maariyo | moorchhit kari prithvee par daariyo |","meaning_en":"","page":1229},{"gurmukhi":"ਬਿਨੁ ਸੁਧਿ ਭਏ ਤਾਹਿ ਲਖ ਲੀਨੋ। ਆਪੁ ਬੇਖਿ ਤਿਹ ਤ੍ਰਿਯ ਕੋ ਕੀਨੋ। ੯੮।","roman":"Binu sudhi bhae taahi lakh leeno | aapu bekhi tih triy ko keeno | 98 |","meaning_en":"","page":1229}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":1229,"lines":[{"gurmukhi":"ਰਥ ਤੇ ਉਤਰਿ ਬਾਰਿ ਲੈ ਆਈ। ਕਾਨ ਲਾਗ ਕਰਿ ਬਾਤ ਸੁਨਾਈ।","roman":"Rath te utri baari lai aaee | kaan laag kari baat sunaaee |","meaning_en":"","page":1229},{"gurmukhi":"ਸੁਨੋ ਨਾਥ ਮੈ ਤ੍ਰਿਯ ਤਿਹਾਰੀ। ਤੁਮ ਕੋ ਜੋ ਪ੍ਰਾਨਨ ਤੇ ਪ੍ਯਾਰੀ। ੯੯।","roman":"Suno naath mai triy tihaaree | tum ko jo praanan te pyaaree | 99 |","meaning_en":"","page":1229}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1229},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":1229,"lines":[{"gurmukhi":"ਜਲ ਸੀਚੇ ਜਾਗਤਿ ਭਯੋ ਅਤਿ ਤਨ ਲਾਗੇ ਘਾਇ।","roman":"Jal seeche jaagti bhayo ati tan laage ghaai |","meaning_en":"","page":1229},{"gurmukhi":"ਭਲੋ ਬੁਰੋ ਖਲ ਅਖਲ ਕੋ ਕਛੂ ਨ ਚੀਨਾ ਜਾਇ। ੧੦੦।","roman":"Bhalo buro khal akhal ko kachhoo na cheenaa jaai | 100 |","meaning_en":"","page":1229}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1229},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":1229,"lines":[{"gurmukhi":"ਤ੍ਰਿਯ ਕੋ ਨਾਮ ਜਬੈ ਸੁਨਿ ਪਾਯੋ। ਘੂਮਤ ਘਾਯਲ ਬਚਨ ਸੁਨਾਯੋ।","roman":"Triy ko naam jabai suni paayo | ghoomat ghaayal bachan sunaayo |","meaning_en":"","page":1229},{"gurmukhi":"ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਕਰਿ ਕਰੀ ਬਡਾਈ। ਕਿਹ ਨਿਮਿਤ ਇਹ ਠਾ ਤੂ ਆਈ। ੧੦੧।","roman":"Dhanny dhanny kari karee badaaee | kih nimit ih thaa too aaee | 101 |","meaning_en":"","page":1229}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1229},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":1229,"lines":[{"gurmukhi":"ਸੁਨੁ ਰਾਜਾ ਮੈ ਲਾਜ ਤਜਿ ਯਾ ਤੇ ਪਹੁੰਚੀ ਆਇ।","roman":"Sunu raajaa mai laaj taji yaa te pahunchee aai |","meaning_en":"","page":1229},{"gurmukhi":"ਜਿਯ ਤੇ ਨਿਰਖਿ ਲਿਆਇ ਹੌ ਮਰੇ ਬਰੌਗੀ ਜਾਇ। ੧੦੨।","roman":"Jiy te nirkhi liaai hau mare baraugee jaai | 102 |","meaning_en":"","page":1229}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":1229,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਘਾਯਲ ਘੂਮਤ ਦ੍ਰਿਗਨ ਮੂੰਦਿ ਬਚਨ ਇਮਿ ਕੀਨ।","roman":"Nrip ghaayal ghoomat drigan moondi bachan imi keen |","meaning_en":"","page":1229},{"gurmukhi":"ਮਨ ਬਾਛਤ ਬਰੁ ਮਾਗਿਯੈ ਮੈ ਤ੍ਰਿਯ ਤੁਮ ਬਰ ਦੀਨ। ੧੦੩।","roman":"Man baachhat baru maagiyai mai triy tum bar deen | 103 |","meaning_en":"","page":1229}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1229},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":1229,"lines":[{"gurmukhi":"ਜਬ ਮੈ ਤੁਹਿ ਜੀਵਤ ਲਿਖ ਲਯੋ। ਜਨੁ ਬਿਧਿ ਨਯੋ ਜਨਮ ਤੁਹਿ ਦਯੋ।","roman":"Jab mai tuhi jeevat likh layo | janu bidhi nayo janam tuhi dayo |","meaning_en":"","page":1229},{"gurmukhi":"ਤਾ ਤੇ ਹ੍ਰਿਦੈ ਸੰਕ ਨਹਿ ਧਰਿਯੈ। ਬਹੁਰਿ ਬ੍ਯਾਹ ਮੋ ਸੌ ਅਬ ਕਰਿਯੈ। ੧੦੪।","roman":"Taa te hridai sank nahi dhariyai | bahuri byaah mo sau ab kariyai | 104 |","meaning_en":"","page":1229}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":1229,"lines":[{"gurmukhi":"ਜੋ ਤ੍ਰਿਯ ਕਹਾ ਵਹੈ ਪਤਿ ਮਾਨ੍ਯੋ। ਭੇਦ ਅਭੇਦ ਕਛੁ ਦੁਖਿਤ ਨ ਜਾਨ੍ਯੋ।","roman":"Jo triy kahaa vahai pati maanyo | bhed abhed kachhu dukhit na jaanyo |","meaning_en":"","page":1229},{"gurmukhi":"ਚਕਮਕ ਝਾਰਿ ਆਗਿ ਤਹ ਜਾਰੀ। ਚਾਰਿ ਭਵਾਰੈ ਲਈ ਪ੍ਯਾਰੀ। ੧੦੫।","roman":"Chakmak jhaari aagi tah jaaree | chaari bhavaarai laee pyaaree | 105 |","meaning_en":"","page":1229}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":1229,"lines":[{"gurmukhi":"ਪੁਨਿ ਬਚਿਤ੍ਰ ਦੇ ਐਸ ਉਚਾਰੌ। ਸੁਨੋ ਨਾਥ ਤੁਮ ਬਚਨ ਹਮਾਰੌ।","roman":"Puni bachitr de ais uchaarau | suno naath tum bachan hamaarau |","meaning_en":"","page":1229},{"gurmukhi":"ਤ੍ਰਿਪਰਾਂਤਕ ਅਰਿ ਅਤਿ ਮੁਹਿ ਭਯੋ। ਤੁਮ ਬਿਨੁ ਮੋਹਿ ਅਧਿਕ ਦੁਖ ਦਯੋ। ੧੦੬।","roman":"Tripraantak ari ati muhi bhayo | tum binu mohi adhik dukh dayo | 106 |","meaning_en":"","page":1229}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":1229,"lines":[{"gurmukhi":"ਤੁਰਤੁ ਨਾਥ ਹਮ ਸੋ ਉਠਿ ਰਮੋ। ਸਭ ਅਪਰਾਧ ਹਮਾਰੋ ਛਮੋ।","roman":"Turtu naath ham so uthi ramo | sabh apraadh hamaaro chhamo |","meaning_en":"","page":1229},{"gurmukhi":"ਤਬ ਰਾਜਾ ਤਿਹ ਸਾਥ ਬਿਹਾਰਿਯੋ। ਤ੍ਰਿਯ ਕੋ ਤਾਪ ਦੂਰਿ ਕਰਿ ਡਾਰਿਯੋ। ੧੦੭।","roman":"Tab raajaa tih saath bihaariyo | triy ko taap doori kari daariyo | 107 |","meaning_en":"","page":1229}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1231},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":1231,"lines":[{"gurmukhi":"ਲਪਟਿ ਲਪਟਿ ਰਾਜਾ ਰਮ੍ਯੋ ਚਿਮਟਿ ਚਿਮਟਿ ਗਈ ਤ੍ਰੀਯ।","roman":"Lapti lapti raajaa ramyo chimti chimti gaee treey |","meaning_en":"","page":1231},{"gurmukhi":"ਬਿਕਟ ਸੁ ਦੁਖ ਝਟਪਟ ਕਟੇ ਅਧਿਕ ਬਢਾ ਸੁਖ ਜੀਯ। ੧੦੮।","roman":"Bikat su dukh jhatpat kate adhik badhaa sukh jeey | 108 |","meaning_en":"","page":1231}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1231},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":1231,"lines":[{"gurmukhi":"ਪਤਿ ਰਤਿ ਕਰਿ ਰਥ ਲਯੋ ਚੜਾਈ। ਬਰਿਯੋ ਪ੍ਰਾਤ ਦੁੰਦਭੀ ਬਜਾਈ।","roman":"Pati rati kari rath layo charaaee | bariyo praat dundbhee bajaaee |","meaning_en":"","page":1231},{"gurmukhi":"ਸਭ ਰਾਜਨ ਕੋ ਦਲ ਬਲ ਹਰਾ। ਆਪਨ ਸੁਭਟ ਸਿੰਘ ਪਤਿ ਕਰਾ। ੧੦੯।","roman":"Sabh raajan ko dal bal haraa | aapan subhat singh pati karaa | 109 |","meaning_en":"","page":1231}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":1231},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":1231,"lines":[{"gurmukhi":"ਤੁਮਲ ਜੁਧੁ ਤਿਹ ਤ੍ਰਿਯ ਕਰਾ ਸਭ ਰਾਜਨ ਕੋ ਘਾਇ।","roman":"Tumal judhu tih triy karaa sabh raajan ko ghaai |","meaning_en":"","page":1231},{"gurmukhi":"ਸੁਭਟ ਸਿੰਘ ਕੋ ਪਤਿ ਕਰਾ ਜੈ ਦੁੰਦਭੀ ਬਜਾਇ।੧੧੦।","roman":"Subhat singh ko pati karaa jai dundbhee bajaai | 110 |","meaning_en":"","page":1231}]},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":1231,"lines":[{"gurmukhi":"ਹੈ ਗੈ ਰਥ ਬਾਜੀ ਹਨੇ ਛੀਨ ਨ੍ਰਿਪਨ ਬਲ ਕੀਨ।","roman":"Hai gai rath baajee hane chheen nripan bal keen |","meaning_en":"","page":1231},{"gurmukhi":"ਸਮਰ ਸੁਯੰਬਰ ਜੀਤਿ ਕਰਿ ਸੁਭਟ ਸਿੰਘ ਪਤਿ ਲੀਨ। ੧੧੧।","roman":"Samar suyanbar jeeti kari subhat singh pati leen | 111 |","meaning_en":"","page":1231}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":1231},{"type":"verse","number":[112,1],"number_text":"੧੧੨। ੧।","page":1231,"lines":[{"gurmukhi":"ਦਾਨਵਿੰਦ੍ਰ ਪ੍ਰਿਥਵੀਸ ਸੰਘਾਰੇ। ਹੈ ਗੈ ਰਥ ਪੈਦਲ ਦਲਿ ਡਾਰੇ।","roman":"Daanvindr prithvees sanghaare | hai gai rath paidal dali daare |","meaning_en":"","page":1231},{"gurmukhi":"ਕਿਸੂ ਬੀਰ ਕੋ ਭੈ ਨ ਧਰਤ ਭੀ। ਸੁਭਟ ਸਿੰਘ ਕਹ ਜੀਤ ਬਰਤ ਭੀ। ੧੧੨। ੧।","roman":"Kisoo beer ko bhai na dharat bhee | subhat singh kah jeet barat bhee | 112 | 1 |","meaning_en":"","page":1231}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਬਾਵਨੋ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade baavno charitr samaaptam","meaning_en":"","page":1231},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੫੨। ੯੯੧। ਅਫਜੂੰ।","roman":"Satu subham satu | 52 | 991 | aphjoon |","meaning_en":"","page":1231}],"page":1231,"number":[52,991]}});
